      "module": "Mathlib.LinearAlgebra.Vandermonde"
    }
  ]
}

{
  "items": [
    {
      "name": "Matrix.det_matrixOfPolynomials",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Block",
      "kind": "theorem",
      "type": "∀ {R : Type v} [inst : CommRing R] {n : ℕ} (p : Fin n → Polynomial R),\n  (∀ (i : Fin n), (p i).natDegree = ↑i) → (∀ (i : Fin n), (p i).Monic) → (Matrix.of fun i j => (p j).coeff ↑i).det = 1"
    },
    {
      "name": "eval_det",
      "module_name": "Mathlib.RingTheory.MatrixPolynomialAlgebra",
      "kind": "theorem",
      "type": "∀ {n : Type w} [inst : DecidableEq n] [inst_1 : Fintype n] {R : Type u_3} [inst_2 : CommRing R]\n  (M : Matrix n n (Polynomial R)) (r : R),\n  Polynomial.eval r M.det = (Polynomial.eval ((Matrix.scalar n) r) (matPolyEquiv M)).det"
    },
    {
      "name": "matPolyEquiv_coeff_apply_aux_2",
      "module_name": "Mathlib.RingTheory.MatrixPolynomialAlgebra",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] {n : Type w} [inst_1 : DecidableEq n] [inst_2 : Fintype n] (i j : n)\n  (p : Polynomial R) (k : ℕ), (matPolyEquiv (Matrix.single i j p)).coeff k = Matrix.single i j (p.coeff k)"
    },
    {
      "name": "Matrix.det_eq_sign_charpoly_coeff",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Charpoly.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] {n : Type v} [inst_1 : DecidableEq n] [inst_2 : Fintype n] (M : Matrix n n R),\n  M.det = (-1) ^ Fintype.card n * M.charpoly.coeff 0"
    },
    {
      "name": "matPolyEquiv_coeff_apply",
      "module_name": "Mathlib.RingTheory.MatrixPolynomialAlgebra",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] {n : Type w} [inst_1 : DecidableEq n] [inst_2 : Fintype n]\n  (m : Matrix n n (Polynomial R)) (k : ℕ) (i j : n), (matPolyEquiv m).coeff k i j = (m i j).coeff k"
    },
    {
      "name": "Polynomial.leadingCoeff_det_X_one_add_C",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Polynomial",
      "kind": "theorem",
      "type": "∀ {n : Type u_1} {α : Type u_2} [inst : DecidableEq n] [inst_1 : Fintype n] [inst_2 : CommRing α] (A : Matrix n n α),\n  (Polynomial.X • 1 + A.map ⇑Polynomial.C).det.leadingCoeff = 1"
    },
    {
      "name": "Matrix.charpoly_coeff_eq_prod_coeff_of_le",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Charpoly.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] {n : Type v} [inst_1 : DecidableEq n] [inst_2 : Fintype n] (M : Matrix n n R)\n  {k : ℕ}, Fintype.card n - 1 ≤ k → M.charpoly.coeff k = (∏ i, (Polynomial.X - Polynomial.C (M i i))).coeff k"
    },
    {
      "name": "Polynomial.coeff_det_X_add_C_card",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Polynomial",
      "kind": "theorem",
      "type": "∀ {n : Type u_1} {α : Type u_2} [inst : DecidableEq n] [inst_1 : Fintype n] [inst_2 : CommRing α] (A B : Matrix n n α),\n  (Polynomial.X • A.map ⇑Polynomial.C + B.map ⇑Polynomial.C).det.coeff (Fintype.card n) = A.det"
    }
  ]
}
